custom.scss:
@import "global-objects";

/* Client-supplied ABC typefaces loaded in templates/layout/base.html. */
:root {
    --sans: "ABC Social", -apple-system, "Helvetica Neue", Arial, sans-serif;
    --sans-ext: "ABC Social Extended", "ABC Social", -apple-system, Arial, sans-serif;
    --serif: "ABC Arizona Text", Georgia, "Times New Roman", serif;
}

body {
    font-family: var(--sans);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
}

:focus-visible {
    outline: 2px solid var(--royal);
    outline-offset: 3px;
}
.app :focus:not(:focus-visible) {
    outline: none;
}

.page_title__sustainably_sourced{
    .accordion-block:has(.accordion-heading[accordion-title="material"]),
    .accordion-block:has(.accordion-heading[accordion-title="brand"]) {
        display: none;
    }
}

/* ══════════════ TYPOGRAPHY SCALE ══════════════
   Headlines  ABC Social Light · sentence/title · 100–120% leading · 0 tracking
   Body       ABC Arizona Text Regular · 130% leading
   Eyebrows   ABC Social Extended Medium · UPPERCASE · 120% leading · 25% tracking
   ============================================== */
.d-hero{font-family:var(--sans);font-weight:300;font-size:clamp(34px,4cqw,58px);line-height:1;letter-spacing:0}
.d-xl  {font-family:var(--sans);font-weight:300;font-size:clamp(32px,4.2cqw,60px);line-height:1.04;letter-spacing:0}
.d-lg  {font-family:var(--sans);font-weight:300;font-size:clamp(26px,3cqw,42px);line-height:1.08;letter-spacing:0}
.d-md  {font-family:var(--sans);font-weight:300;font-size:clamp(21px,2cqw,28px);line-height:1.14;letter-spacing:0}
.d-sm  {font-family:var(--sans);font-weight:300;font-size:clamp(17px,1.3cqw,20px);line-height:1.2;letter-spacing:0}

/* the brand "mix headline style" — sans light + Arizona light italic */
.mix {
    font-family: var(--serif);
    font-style: italic;
    font-weight: 300;
    letter-spacing: 0;
}
.lede {
    font-family: var(--serif);
    font-weight: 400;
    font-size: clamp(17px, 1.25cqw, 20px);
    line-height: 1.42;
    letter-spacing: 0;
    color: var(--ink-72);
}
.body {
    font-family: var(--serif);
    font-weight: 400;
    font-size: 16px;
    line-height: 1.45;
    color: var(--ink-72);
}
.body-sm {
    font-family: var(--serif);
    font-weight: 400;
    font-size: 14.5px;
    line-height: 1.45;
    color: var(--ink-72);
}

.container {
    width: 100%;
    max-width: 1512px;
    margin-inline: auto;
    padding-inline: 56px;
    -webkit-box-sizing: border-box;
    box-sizing: border-box;
}

[data-content-region="page_main_banner"] {
    [data-sub-layout] {
        padding: 0 !important;
    }
}

/* Main category banner lives globally so its content and image can be managed
   through Page Builder without relying on the category-grid stylesheet. */
.top-category-hero {
    position: relative;
    width: 100%;
    min-height: 260px;
    aspect-ratio:3.2 / 1;
    margin-bottom: 48px;
    overflow: hidden;
    background: #d9d9d9;

    .btn {
        width: auto;
        display: inline-flex;
        margin-top: 20px;
        font-size: 16px;
        padding: 12px 24px !important;
    }

    &__image,
    &__fallback {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
    }

    &__image,
    &__fallback {
        object-fit: cover;
        object-position: center;
    }

    &__shade {
        position: absolute;
        inset: 0;
        background: linear-gradient(90deg, rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.15) 70%);
    }

    &__content {
        position: absolute;
        inset: 0;
        display: flex;
        flex-direction: column;
        justify-content: flex-end;
        align-items: flex-start;
        width: 100%;
        max-width: 1512px;
        margin-inline: auto;
        padding-inline: 56px;
        padding-bottom: 48px;
        box-sizing: border-box;
        color: #fff;
    }

    &__eyebrow,
    .top-category-page__eyebrow {
        display: block;
        font-family: var(--sans-ext);
        font-size: 14px;
        font-weight: 500;
        line-height: 1.2;
        letter-spacing: 0.025em;
        text-transform: uppercase;
    }

    &__title {
        max-width: 22ch;
        margin: 12px 0 0;
        color: inherit;
        font-family: var(--sans);
        font-size: clamp(21px, 2vw, 34px);
        font-weight: 300;
        line-height: 1.14;
        letter-spacing: 0;
    }

    [data-content-region="category_banner_image"] {
        padding: 0 !important;
        * {
            width: 100% !important;
            height: 100% !important;
            position: absolute !important;
            padding: 0 !important;
            object-fit: cover !important;
            object-position: center right !important;
        }
    }
}

@media (max-width: 1360px) {
    .top-category-hero__content {
        padding-inline: 40px;
    }
}

@media (max-width: 980px) {
    .top-category-hero__content {
        padding-inline: 32px;
    }
}

@media (max-width: 760px) {
    .top-category-hero {
        height: 300px;
        min-height: 0;
        aspect-ratio: auto;
    }
}

@media (max-width: 620px) {
    .top-category-hero {
        height: 300px;
        margin-bottom: 32px;
    }

    .top-category-hero__content {
        padding-inline: 20px;
        padding-bottom: 32px;
    }
}

@media (max-width: 390px) {
    .top-category-hero__content {
        padding-inline: 16px;
    }
}


.helpbox {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--s5);
    border: 1px solid var(--hair-strong);
    padding: 20px;
    margin: 20px 0;

    .eyebrow{
        font-family:var(--sans-ext);font-weight:500;
        font-size:14px;line-height:1.2;letter-spacing:.025em;text-transform:uppercase;color:var(--ink);
    }
    .eyebrow.muted{color:var(--ink-52)}

}
.helpbox .btn {
    white-space: nowrap;
    flex: none;
}
.helpbox p {
    margin: 0;
    max-width: 38ch;
}

@include md-phone {.helpbox{flex-direction:column;align-items:flex-start;gap:14px}.helpbox .btn{width:100%}}

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    font-family: var(--sans-ext);
    font-weight: 500;
    font-size: 12.5px;
    letter-spacing: 0.025em;
    text-transform: uppercase;
    padding: 17px 30px;
    border: 1px solid var(--black);
    background: var(--black);
    color: var(--white);
    min-height: 48px;
    position: relative;
    overflow: hidden;
    transition:
        color var(--dur) var(--ease),
        border-color var(--dur) var(--ease);
}
.btn::after {
    content: "";
    position: absolute;
    inset: 0;
    background: var(--white);
    transform: translateY(101%);
    transition: transform var(--dur) var(--ease);
    z-index: 0;
}
.btn > * {
    position: relative;
    z-index: 1;
}
.btn:hover {
    color: var(--black);
}
.btn:hover::after {
    transform: translateY(0);
}
.btn-ghost {
    background: transparent;
    color: var(--black);
    border-color: var(--black);
}
.btn-ghost::after {
    background: var(--black);
}
.btn-ghost:hover {
    color: var(--white);
}
.btn-line {
    background: transparent;
    color: var(--white);
    border-color: rgba(255, 255, 255, 0.55);
}
.btn-line::after {
    background: var(--white);
}
.btn-line:hover {
    color: var(--black);
    border-color: var(--white);
}
.btn-sm {
    padding: 12px 20px;
    min-height: 40px;
    font-size: 12px;
}
.btn-block {
    display: flex;
    width: 100%;
}
.btn:disabled {
    opacity: 0.35;
    pointer-events: none;
}

.btn-with-outline {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    font-family: var(--sans-ext);
    font-weight: 500;
    font-size: 12.5px;
    letter-spacing: 0.025em;
    text-transform: uppercase;
    padding: 17px 30px;
    border: 1px solid var(--black);
    background: #fff;
    color: #000;
    min-height: 48px;
    position: relative;
    overflow: hidden;
    transition: color var(--dur) var(--ease), border-color var(--dur) var(--ease);
}
.btn-with-outline::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateY(101%);
    transition: transform var(--dur) var(--ease);
    z-index: 0;
    background: var(--black);
    color: var(--white);
}
.btn-with-outline > * {
    position: relative;
    z-index: 1;
}
.btn-with-outline:hover {
    color: #fff;
}
.btn-with-outline:hover::after {
    transform: translateY(0);
}

div[data-sub-layout] {
    padding: 0;
    + [data-sub-layout] {
        padding-left: 15px;
    }
}

.section-sm{
    .eyebrow{
        font-family:var(--sans-ext);font-weight:500;
        font-size:11px;line-height:1.2;letter-spacing:.025em;text-transform:uppercase;color:var(--ink);
    }
}
.ship-grid{
    display:grid;grid-template-columns:repeat(3,1fr);gap:var(--s5);margin-top:var(--s5);
    .micro{
       font-family:var(--sans-ext);font-weight:500;
        font-size:10px;letter-spacing:.025em;text-transform:uppercase;color:var(--ink-52);
    }
    .eyebrow.muted{color:var(--ink-52)}
}
.ship-card{border:1px solid var(--hair);padding:26px 24px;display:grid;gap:10px}
.ship-card .k{font-weight:300}
@include md-phone {.ship-grid{grid-template-columns:1fr}}

/* Contact page — mirrors the approved Twelve prototype. */
.page_type__contact_us,
.page_type__page_contact_form,
.page_title__contact {
    .body { margin-bottom: 0; }
    .body > .container { max-width: none; padding: 0; }
}

.twelve-contact-shell {
    box-sizing: border-box;
    width: 100%;
    max-width: var(--maxw);
    margin: 0 auto;
    padding: 0 var(--gutter) var(--s9);

    .breadcrumbs { margin: 28px 0 64px; text-align: left; }
}

.twelve-contact {
    display: grid;
    grid-template-columns: minmax(0, 1.15fr) minmax(380px, .85fr);
    gap: clamp(40px, 5vw, 96px);
    align-items: start;
}

.twelve-contact__intro { min-width: 0; }

.twelve-contact__eyebrow,
.twelve-contact .form-label {
    display: block;
    margin: 0;
    color: var(--ink);
    font-family: var(--sans-ext);
    font-size: 14px;
    font-weight: 500;
    line-height: 1.2;
    letter-spacing: .025em;
    text-transform: uppercase;
}

.twelve-contact__title {
    max-width: 14ch;
    margin: 16px 0 var(--s5);
    color: var(--ink);
    font-family: var(--sans);
    font-size: clamp(40px, 4.2vw, 60px);
    font-weight: 300;
    line-height: 1.04;
    letter-spacing: 0;
}

.twelve-contact__lede {
    max-width: 46ch;
    margin: 0;
    color: var(--ink-72);
    font-family: var(--serif);
    font-size: clamp(17px, 1.25vw, 20px);
    font-weight: 400;
    line-height: 1.42;
}

.twelve-contact__offices {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--s6) var(--s7);
    margin-top: var(--s7);
    padding-top: var(--s6);
    border-top: 1px solid var(--black);
}

.twelve-contact__office {
    display: grid;
    gap: 12px;
    align-content: start;
    margin: 0;
    font-style: normal;

    p,
    a {
        margin: 0;
        color: var(--ink-72);
        font-family: var(--serif);
        font-size: 15px;
        font-weight: 400;
        line-height: 1.45;
    }

    a {
        width: 100%;
        padding-bottom: 3px;
        color: var(--ink);
        border-bottom: 1px solid var(--black);
        word-break: break-word;
        transition: opacity var(--dur) var(--ease);
        &:hover { color: var(--ink); opacity: .55; }
    }
}

.twelve-contact__shipping {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--s5);
    margin-top: var(--s7);
    padding-top: var(--s6);
    border-top: 1px solid var(--hair);

    p {
        margin: 6px 0 0;
        color: var(--ink-72);
        font-family: var(--serif);
        font-size: 14.5px;
        line-height: 1.45;
    }
}

.twelve-contact__detail-link {
    flex: none;
    padding-bottom: 4px;
    color: var(--ink);
    border-bottom: 1px solid var(--black);
    font-family: var(--sans-ext);
    font-size: 10px;
    font-weight: 500;
    letter-spacing: .025em;
    text-transform: uppercase;
    transition: opacity var(--dur) var(--ease);
    &:hover { color: var(--ink); opacity: .55; }
    span { margin-left: 8px; }
}

.twelve-contact__card {
    width: 100%;
    min-width: 0;
    position: sticky;
    top: 128px;
    padding: clamp(26px, 2.6vw, 40px);
    border: 1px solid var(--black);

    .contact-loadingOverlay {
        position: absolute;
        inset: 0;
        z-index: 5;
    }
}

.twelve-contact__form-title {
    margin: 0;
    color: var(--ink);
    font-family: var(--sans);
    font-size: clamp(21px, 2vw, 28px);
    font-weight: 300;
    line-height: 1.14;
    letter-spacing: 0;
}

.twelve-contact__form-intro,
.twelve-contact__signed-in {
    margin: 10px 0 0;
    color: var(--ink-72);
    font-family: var(--serif);
    font-size: 14.5px;
    line-height: 1.45;
}

.twelve-contact__signed-in { margin-top: 0; font-size: 14.5px; }

.twelve-contact .form {
    margin-top: var(--s5);

    .form-row,
    .form-field { display: block; width: 100%; max-width: none; margin: 0; padding: 0; }
    .form-field { margin-bottom: 18px; }
    .form-label { margin-bottom: 8px; }
    .form-label small { display: none; }

    .form-input {
        width: 100%;
        min-height: 42px;
        padding: 10px 0;
        color: var(--ink);
        border: 0;
        border-bottom: 1px solid var(--black);
        border-radius: 0;
        background: transparent;
        box-shadow: none;
        font-family: var(--serif);
        font-size: 14px;
        line-height: 1.45;
        &:focus { border-color: var(--black); box-shadow: none; }
    }

    .form-select {
        width: 100%;
        min-height: 42px;
        padding: 10px 28px 10px 0;
        color: var(--ink);
        border: 0;
        border-bottom: 1px solid var(--black);
        border-radius: 0;
        background-color: transparent;
        font-family: var(--serif);
        font-size: 14px;
        line-height: 1.45;
    }

    .twelve-contact__file-input {
        min-height: 44px;
        padding: 8px;
        border: 1px dashed var(--hair-strong);
        font-family: var(--sans);
        font-size: 12px;
    }

    .twelve-contact__routing-note {
        margin: 2px 0 18px;
        color: var(--ink-52);
        font-family: var(--serif);
        font-size: 14px;
        line-height: 1.45;
    }

    .twelve-contact__upload-help,
    .twelve-contact__upload-status {
        margin: 7px 0 0;
        color: var(--ink-52);
        font-family: var(--serif);
        font-size: 12.5px;
        line-height: 1.45;
    }

    .twelve-contact__upload-status.is-success { color: var(--emerald); }
    .twelve-contact__upload-status.is-error { color: var(--crimson); }

    .twelve-contact__upload-status a {
        color: inherit;
        border-bottom: 1px solid currentColor;
        transition: opacity var(--dur) var(--ease);

        &:hover { color: inherit; opacity: .6; }
    }

    textarea.form-input { min-height: 110px; padding-top: 8px; resize: vertical; }
    .form-inlineMessage { margin-top: 6px; font-family: var(--serif); font-size: 12px; }
    .g-recaptcha { max-width: 100%; margin: 0 0 18px; overflow: hidden; }
    .form-actions { margin-top: 20px; text-align: left; }

    .button--primary {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 100%;
        min-height: 48px;
        margin: 0;
        padding: 15px 30px;
        overflow: hidden;
        position: relative;
        z-index: 0;
        color: var(--white);
        border: 1px solid var(--black);
        border-radius: 0;
        background: var(--black);
        font-family: var(--sans-ext);
        font-size: 12.5px;
        font-weight: 500;
        letter-spacing: .025em;
        line-height: 1.2;
        text-transform: uppercase;
        transition: color var(--dur) var(--ease);

        &::after {
            content: "";
            position: absolute;
            inset: 0;
            z-index: -1;
            background: var(--white);
            transform: translateY(101%);
            transition: transform var(--dur) var(--ease);
        }

        &:hover,
        &:focus { color: var(--black); border-color: var(--black); background: var(--black); }
        &:hover::after,
        &:focus::after { transform: translateY(0); }
    }
}

@media (max-width: 991px) {
    .twelve-contact-shell { padding-inline: 32px; }
    .twelve-contact { grid-template-columns: minmax(0, 1fr); gap: var(--s8); }
    .twelve-contact__card { position: relative; top: auto; }
}

@media (max-width: 767px) {
    .twelve-contact-shell {
        padding-inline: 20px;
        .breadcrumbs { margin-bottom: 40px; }
    }
    .twelve-contact__title { font-size: clamp(36px, 11vw, 48px); }
    .twelve-contact__offices { grid-template-columns: 1fr; }
    .twelve-contact__shipping { align-items: flex-start; flex-direction: column; gap: 14px; }
}


