.alertBox, .alertBoxInfo{
    padding: 10px 50px 10px 16px;
    border-radius: 8px;
    border: 1px solid #707070;
    position: relative;

    .links{
      color: #1677FF;
      cursor: pointer;
      &:hover{
        text-decoration: underline !important;
        text-underline-offset: 5px;
      }
    }

    &.alertBoxInfo {
      padding: 10px 10px 10px 16px;

      &.card-success-edit-message p {
          color: #003D77;
      }

      &.card-error-edit-message p {
          color: #820014;
      }
    }

    .alertBox-message, .alertBoxInfo-message{

        font-size: 14px;
        font-weight: 700;
        line-height: 22px;
        text-align: left;
        color: #1d1d1d;
        margin: 0;
        span{
          width: 100%;
        }

        &.color-gold {
            color: #874D00;
        }
    }

    .alertBox-column{
        vertical-align: text-top;
    }

    .icon {
        height: 18px;
        width: 20px;
        margin: -2px 0 0 0;
    }

    .alertBox-large{
      vertical-align: middle !important;
      position: relative;
      top:-2px;
      .icon{
        width: 25px;
        height: 25px;
      }
    }

    .alertBox-content{
      display: flex;
      gap: 20px;
      align-items: center;
      width: 100%;
      &.is-fit{
        justify-content: space-between;
      }
      .ac-head {
        width: 100%;
        font-weight: bold;
        font-size: 18px;
        line-height: 22px;
        color: #1D1D1D;
        margin: 0 0 5px 0;
      }
      .ac-content{
        width: 100%;
        font-size: 14px;
        line-height: 20px;
        margin: 0;
        a{
          text-decoration: underline !important;
          text-underline-offset: 4px;
          font-weight: 600;
        }
      }

      .button{
        border-color: #003D77 !important;
        color: #003D77;
        margin: 0;
        padding: 8px 15px;
        min-width: 100px;
        font-weight: 400;
        &:focus{
          outline: none !important;
        }
        &:hover{
          border-color: #1d1d1d !important;
          color: #1d1d1d;
        }
      }

      .button--link{
        color: #1677FF;

        font-size: 14px;
        font-style: normal;
        font-weight: 400;
        text-decoration: underline !important;
        text-underline-offset: 5px;
        height: 32px;
        line-height: 30px;
        padding: 0 16px;
        text-align: center;
        @include emd-phone{
          font-size: 12px;
          font-style: normal;
          font-weight: 400;
          padding: 0 10px;
        }
        &:focus{
          outline: none !important;
        }
        &:hover{
          text-decoration: none !important;
        }
      }

      .button--white{
        border-radius: 6px;
        border: 1px solid #CCC;
        background: #FFF;
        box-shadow: 0 2px 0 0 rgba(0, 0, 0, 0.02);
        color: #1D1D1D;

        font-size: 14px;
        font-style: normal;
        font-weight: 400;
        min-width: auto;
        height: 32px;
        line-height: inherit;
        padding: 0 16px;
        @include emd-phone{
          font-size: 12px;
          font-style: normal;
          font-weight: 400;
          line-height: 20px; 
          padding: 0 10px;
        }
        &:focus{
          outline: none !important;
        }
        &:hover{
          color: #005AAF;
        }
      }
    }

    .alertBox-content + .alertBox-close {
      @include sm-desktop {
        height: 30px;
      }
    }

    .alertBox-close{
        cursor: pointer;
        padding: 0;
        position: absolute;
        top: 0px;
        width: 30px;
        height: 43px;
        right: 5px;
        border-radius: 8px;
        &:focus{
          outline: none !important;
        }
        svg{
            width: 22px;
            height: 22px;
            display: block;
            margin: 0 auto;
            fill: rgba($color: #000, $alpha: 0.88) !important;
        }
        &:hover, &:focus {
            background-color:transparent !important;
            border-color: transparent;
        }
    }


  &.small-inline{
    @include emd-phone{
        align-items: flex-start;
        justify-content: flex-start;
        display: flex;
    }
    .alertBox-large {
      padding-right: 10px;
      top: -1px;
      .icon{
        width: 16px;
        height: 16px;
        margin: 0;
      }
    }
    .alertBox-content{
      .ac-head{
        font-size: 14px;
        line-height: 20px; 
        font-style: normal;
        font-weight: 600;
        margin: 0;
        padding-right: 25px;
      }
      .ac-center{
        display: flex;
        justify-content: flex-start;
        align-items: center;
        flex-wrap: wrap;
      }
      @include emd-phone{
        flex-wrap: wrap;
        gap: 10px;
        .ac-center{
          flex-basis: 100%;
          width: 100%;
          gap: 10px;
          a,button{
            flex: 1;
          }
        }
      }
    } 
  }

  &.is-extra-small{
    padding: 8px 16px;
    .alertBox-content{
      .ac-center{
        justify-content: end;
        min-width: 162px;
      }
    } 
  }

  &.alertBoxInfo--info,
   &.alertBox--info{
       background: #E6F4FF;
       border-color:#91CAFF;
       svg{ fill: #003D77; }
   }

   &.alertBoxInfo--success,
   &.alertBox--success{
       background: #F6FFED;
       border-color:#B7EB8F;
       svg{ fill: #52C41A; }
   }

   &.alertBoxInfo--warning,
   &.alertBox--warning{
       background:#FFFBE6;
       border-color: #FFE58F;
       svg{ fill:#FAAD14; }
   }

   &.alertBoxInfo--error,
   &.alertBox--error {
       background:#FFF1F0;
       border-color: #FFA39E;
       svg{ fill:#FF4D4F; }
   }

}


