// Guest access screen
.twelve-guest-screen {
    background: #f4f1eb;
    display: flex;
    inset: 0;
    min-height: 100vh;
    position: fixed;
    z-index: 100;
}

.twelve-guest-art,
.twelve-guest-content {
    align-items: center;
    display: flex;
    flex: 1 1 50%;
    justify-content: center;
}

.twelve-guest-art {
    background: #151512;
    color: #fff;
    overflow: hidden;
    padding: clamp(40px, 7vw, 120px);
    position: relative;
}

.twelve-guest-art::before {
    border: 1px solid rgba(255, 255, 255, .14);
    border-radius: 50%;
    content: "";
    height: 43vw;
    max-height: 680px;
    max-width: 680px;
    position: absolute;
    right: -18vw;
    top: -12vw;
    width: 43vw;
}

.twelve-guest-art::after {
    background: #b9a27b;
    bottom: 0;
    content: "";
    height: 7px;
    left: 0;
    position: absolute;
    width: 100%;
}

.twelve-guest-art-inner { max-width: 540px; position: relative; z-index: 1; }
.twelve-guest-kicker {
    color: #b9a27b;
    display: block;
    font-size: 16px;
    letter-spacing: .24em;
    margin-bottom: 30px;
    text-transform: uppercase;
}

.twelve-guest-art h2 {
    color: #fff;
    font-family: var(--serif, Georgia, serif);
    font-size: clamp(48px, 6vw, 94px);
    font-weight: 400;
    letter-spacing: -.045em;
    line-height: .98;
    margin: 0 0 34px;
}

.twelve-guest-art p {
    color: rgba(255, 255, 255, .68);
    font-size: 18px;
    line-height: 1.8;
    margin: 0 0 28px;
    max-width: 400px;
}

.twelve-guest-locations {
    color: #fff;
    font-size: 16px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
}

.twelve-guest-content { background: #f4f1eb; padding: 60px; }
.twelve-guest-card { max-width: 560px; width: 100%; }

.twelve-guest-logo { margin: 0 0 clamp(70px, 10vh, 130px); max-width: 190px; }
.twelve-guest-logo .header-logo__link { display: block; }
.twelve-guest-logo .header-logo-image-container { max-width: 190px; }
.twelve-guest-logo .header-logo-image,
.twelve-guest-logo .header-logo-image-unknown-size { max-height: 68px; width: auto; }
.twelve-guest-logo .header-logo-text { font-size: 38px; line-height: 1; }

.twelve-guest-card h3 {
    color: #151512;
    font-size: clamp(32px, 3vw, 48px);
    font-weight: 400;
    letter-spacing: -.035em;
    line-height: 1.08;
    margin: 0 0 20px;
    white-space: nowrap;
}

.twelve-guest-card > p {
    color: #000;
    font-size: 18px;
    line-height: 1.75;
    margin: 0 0 38px;
    max-width: 390px;
}

.twelve-guest-actions { display: flex; gap: 12px; }
.twelve-guest-actions .btn-with-outline { font-size: 16px; margin: 0; min-width: 150px; }
.twelve-guest-actions .event-open-signin { background: #151512; color: #fff; }
.twelve-guest-actions .event-open-signin::after { background: #b9a27b; }

@media (max-width: 800px) {
    .twelve-guest-screen { display: flex; flex-direction: column; overflow-y: auto; }
    .twelve-guest-content { min-height: 62vh; order: 1; padding: 48px 28px; }
    .twelve-guest-art { align-items: flex-end; min-height: 38vh; order: 2; padding: 48px 28px; }
    .twelve-guest-art::before { height: 300px; right: -130px; top: -130px; width: 300px; }
    .twelve-guest-art h2 { font-size: clamp(42px, 12vw, 68px); margin-bottom: 18px; }
    .twelve-guest-art p { display: none; }
    .twelve-guest-kicker { margin-bottom: 18px; }
    .twelve-guest-logo { margin-bottom: 52px; }
}

@media (max-width: 480px) {
    .twelve-guest-actions { flex-direction: column; }
    .twelve-guest-actions .btn-with-outline { width: 100%; }
}

